package com.nook.widgets;

import android.app.*;
import android.content.Context;
import android.graphics.*;
import android.media.session.PlaybackState;
import android.os.SystemClock;
import android.view.View;
import android.widget.RemoteViews;
import org.json.JSONObject;

public final class CreativeMusic {
    private CreativeMusic(){}
    public static final String[] NAMES={"Cassette Deck","Orbit Disc","Cover Stack","Bubble Lab","Soft Sculpt","Paper Cut","Pixel Arcade"};
    public static RemoteViews render(Context c,int id,JSONObject config,boolean small,boolean preview){
        int variant=WidgetDesign.clamp(config.optInt("variant",4),4,10);MusicState state=new MusicState(c,config);int[] size=WidgetDesign.size(c,id,"music",config,small);boolean rail=variant==5&&size[1]>=230;JSONObject typography=config;try{if(!config.has("font")&&config.optInt("musicMood",0)==0&&WidgetDesign.id(config)==0){typography=new JSONObject(config.toString());if(variant==4||variant==10)typography.put("font",3);if(variant==9)typography.put("font",4);}}catch(Exception ignored){}
        RemoteViews v=new RemoteViews(c.getPackageName(),WidgetDesign.layout(c,rail?"creative_music_orbit":"creative_music",typography));WidgetDesign.Colors design=WidgetDesign.colors(config,"music");int[] colors=CreativeArt.palette(config,design,state.art,variant);int[] bg={R.id.widget_action_bg0,R.id.widget_action_bg1,R.id.widget_action_bg2};v.setImageViewResource(R.id.widget_surface,Widgets.surfaceResource(config,"music"));WidgetDesign.surfaces(c,v,id,"music",config,false,bg);if(config.optInt("style",0)==0)v.setImageViewBitmap(R.id.widget_surface,CreativeArt.panel(colors[0],320,Math.max(80,320*size[1]/Math.max(1,size[0])),WidgetDesign.radius(config)*320f/Math.max(1,size[0]),config.optBoolean("musicTexture",true)&&(variant==4||variant==9||variant==10)));
        v.setInt(R.id.widget_surface,"setImageAlpha",Widgets.surfaceAlpha(config));v.setImageViewBitmap(R.id.music_scene,CreativeArt.scene(config,state,variant,480,variant==5?300:200,colors));int pad=small?10:14;v.setViewPadding(R.id.widget_root,Ui.dp(c,pad),Ui.dp(c,10),Ui.dp(c,pad),Ui.dp(c,10));boolean embedded=config.optBoolean("_embedded",false),hidden=config.optBoolean("musicHideText",false);
        v.setTextViewText(R.id.widget_label,config.optString("title","").isEmpty()?NAMES[variant-4].toUpperCase(java.util.Locale.ROOT):config.optString("title"));v.setViewVisibility(R.id.widget_header,hidden||embedded?View.GONE:View.VISIBLE);v.setViewVisibility(R.id.widget_label,config.optBoolean("showLabel",true)?View.VISIBLE:View.INVISIBLE);v.setViewVisibility(R.id.music_copy,hidden?View.GONE:View.VISIBLE);
        v.setInt(R.id.widget_title,"setMaxLines",size[1]>=210?2:1);boolean access=MediaAccess.allowed(c);v.setTextViewText(R.id.widget_title,state.connected?state.title:access?"Ready when you are":"Connect your music");v.setTextViewText(R.id.widget_body,state.connected?state.artist:access?"Start your player":"Enable media access");v.setTextViewText(R.id.widget_meta,state.connected?state.status+(config.optBoolean("musicShowAlbum",true)&&!state.album.isEmpty()?" · "+state.album:"")+(config.optBoolean("musicShowApp",true)?" · "+state.app:""):"Choose a player in Options");v.setViewVisibility(R.id.widget_meta,size[1]<210?View.GONE:View.VISIBLE);
        for(int text:new int[]{R.id.widget_title,R.id.widget_label})v.setTextColor(text,colors[1]);for(int text:new int[]{R.id.widget_body,R.id.widget_meta,R.id.music_elapsed,R.id.music_duration})v.setTextColor(text,colors[2]);v.setTextViewTextSize(R.id.widget_title,android.util.TypedValue.COMPLEX_UNIT_SP,(size[1]<210?17:21)*WidgetDesign.scale(config));v.setTextViewTextSize(R.id.widget_body,android.util.TypedValue.COMPLEX_UNIT_SP,12*WidgetDesign.scale(config));
        boolean timeline=state.connected&&!hidden&&config.optBoolean("musicProgress",true);v.setViewVisibility(R.id.music_timeline,timeline?View.VISIBLE:View.GONE);v.setImageViewBitmap(R.id.widget_progress,MusicArt.progress(state.position,state.duration,colors[3],colors[2]));v.setChronometer(R.id.music_elapsed,SystemClock.elapsedRealtime()-state.position,null,state.playback!=null&&state.playback.getState()==PlaybackState.STATE_PLAYING&&state.playback.getPlaybackSpeed()==1&&state.duration>0);v.setTextViewText(R.id.music_duration,state.duration>0?MusicState.time(state.duration):"LIVE");
        String[] ops={config.optInt("musicTransport",0)==1?"back":"previous","toggle",config.optInt("musicTransport",0)==1?"forward":"next"};String[] names={ops[0].equals("back")?"Back 15 seconds":"Previous track",state.playing?"Pause playback":"Play",ops[2].equals("forward")?"Forward 30 seconds":"Next track"};int[] icons={R.drawable.ic_music_previous,state.playing?R.drawable.ic_music_pause:R.drawable.ic_music_play,R.drawable.ic_music_next};v.setViewVisibility(R.id.widget_actions,state.connected?View.VISIBLE:View.GONE);
        for(int n=0;n<3;n++){int button=new int[]{R.id.widget_action0,R.id.widget_action1,R.id.widget_action2}[n];int fill=n==1?colors[3]:MusicArt.mix(colors[0],colors[1],.12f),ink=n==1&&variant!=8?MusicArt.contrast(colors[3]):colors[1];v.setImageViewBitmap(bg[n],CreativeArt.button(variant,fill,colors[0],60,52,config.optInt("musicDepth",65)/100f));v.setInt(bg[n],"setImageAlpha",Widgets.surfaceAlpha(config));v.setImageViewResource(button,icons[n]);v.setInt(button,"setColorFilter",ink);if(n!=1&&config.optInt("musicTransport",0)==1)v.setImageViewBitmap(button,MusicArt.skip(n==0?-15:30,ink));boolean enabled=state.can(ops[n]);v.setBoolean(button,"setEnabled",enabled);v.setInt(button,"setImageAlpha",enabled?255:65);v.setContentDescription(button,names[n]+(enabled?"":" · unavailable in this player"));if(!preview)v.setOnClickPendingIntent(button,enabled?MusicWidgets.transport(c,id,state,ops[n]):null);}
        v.setImageViewResource(R.id.widget_settings,R.drawable.ic_music_options);v.setImageViewResource(R.id.music_expand,R.drawable.ic_music_expand);for(int icon:new int[]{R.id.widget_settings,R.id.music_expand})v.setInt(icon,"setColorFilter",colors[1]);v.setViewVisibility(R.id.widget_settings,embedded?View.GONE:View.VISIBLE);v.setContentDescription(R.id.widget_root,NAMES[variant-4]+". "+state.title+". "+state.artist+". "+state.status);v.setContentDescription(R.id.music_scene,variant==7?"Sculpted bubbles show the player's reported output volume":variant==6?"Layered covers use shared queue artwork when available":"Original decorative music object");
        if(!preview){PendingIntent detail=MusicWidgets.details(c,id,false);v.setOnClickPendingIntent(R.id.widget_root,detail);v.setOnClickPendingIntent(R.id.music_scene,MusicWidgets.details(c,id,config.optInt("musicTap",0)==1));v.setOnClickPendingIntent(R.id.widget_progress,detail);v.setOnClickPendingIntent(R.id.music_expand,detail);v.setOnClickPendingIntent(R.id.widget_settings,LibraryWidgets.configure(c,id,"music"));}return v;
    }
}
